package dev.kelmagic.client;
import dev.kelmagic.*;import dev.kelmagic.network.SpellSnapshot;import net.minecraft.client.*;import net.minecraft.client.gui.screens.TitleScreen;import net.minecraft.core.registries.Registries;import net.minecraft.resources.*;import net.minecraft.core.component.DataComponents;import net.minecraft.world.item.armortrim.*;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.*;import net.neoforged.fml.common.EventBusSubscriber;
/** Optional benchmark, excluded from release. Measures controlled native-client frames, not user hardware. */
@EventBusSubscriber(modid=KelMagic.MODID,value=Dist.CLIENT)public final class QaPerf {
 static boolean opened,ready;static int wait,frames,phase;static long last;static final java.util.List<Double> times=new java.util.ArrayList<>();static final java.util.List<String> words=java.util.Collections.nCopies(100,"muk");
 @SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post e){if(!Boolean.getBoolean("kelmagic.perfQA"))return;var mc=Minecraft.getInstance();if(mc.level==null){if(!opened&&mc.screen instanceof TitleScreen&&++wait>40){opened=true;mc.createWorldOpenFlows().openWorld("KelMagicQA",()->{});}return;}if(!ready){mc.setScreen(null);mc.options.enableVsync().set(false);mc.options.framerateLimit().set(260);mc.options.renderDistance().set(6);mc.options.guiScale().set(1);mc.resizeDisplay();mc.player.setYRot(0);mc.player.setXRot(0);ready=true;System.out.println("PERF_QA_READY");}ClientSpellState.own=new SpellSnapshot(mc.player.getUUID(),1,phase==1?100:0,500,974,phase==1?words:java.util.List.of(),SpellSnapshot.SYNC);if(phase==1)ClientSpellState.VISUALS.computeIfAbsent(mc.player.getUUID(),u->new ClientSpellState.Visual(words));else ClientSpellState.VISUALS.clear();}
 @SubscribeEvent(priority=EventPriority.LOWEST)public static void frame(net.neoforged.neoforge.client.event.RenderGuiEvent.Post e){if(!Boolean.getBoolean("kelmagic.perfQA")||!ready)return;long now=System.nanoTime();if(last!=0&&frames>240)times.add((now-last)/1e6);last=now;if(++frames>=480){times.sort(Double::compare);double sum=times.stream().mapToDouble(Double::doubleValue).sum();System.out.printf(java.util.Locale.ROOT,"PERF_QA phase=%d n=%d mean_ms=%.3f p50=%.3f p95=%.3f%n",phase,times.size(),sum/times.size(),times.get(times.size()/2),times.get((int)(times.size()*.95)));frames=0;times.clear();last=0;if(++phase==2){System.out.println("PERF_QA_COMPLETE");Minecraft.getInstance().stop();}}}
}
